import React, { useState, useEffect } from 'react';
import { uploadFile, getFiles, downloadFile, deleteFile } from '../services/api';
import CryptoFlow from '../components/CryptoFlow';
import { Upload, Download, FileText, AlertTriangle, Server, HardDrive, Terminal, Trash2, Activity, Play, X, RefreshCw } from 'lucide-react';
import { Bar } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const Dashboard = () => {
  const [files, setFiles] = useState([]);
  const [fileToUpload, setFileToUpload] = useState(null);
  const [uploadStep, setUploadStep] = useState(0); 
  const [error, setError] = useState(null);
  const [logs, setLogs] = useState([]); 
  const [selectedFile, setSelectedFile] = useState(null); 
  const [showDeleteModal, setShowDeleteModal] = useState(null);
  const [successMode, setSuccessMode] = useState(false); // New state for "Upload Another"

  const [storageMode, setStorageMode] = useState('local');
  const [cryptoMode, setCryptoMode] = useState('hybrid'); 

  useEffect(() => {
    fetchFiles();
  }, []);

  const addLog = (msg) => {
    const timestamp = new Date().toLocaleTimeString('en-US', { hour12: false });
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const fetchFiles = async () => {
    try {
      const res = await getFiles();
      setFiles(res.data);
    } catch (err) { console.error("Fetch failed"); }
  };

  const confirmDelete = async () => {
      if (!showDeleteModal) return;
      try {
          await deleteFile(showDeleteModal);
          addLog(`WARN: File ID ${showDeleteModal} permanently erased.`);
          fetchFiles();
          if (selectedFile?.id === showDeleteModal) setSelectedFile(null);
      } catch (err) {
          setError("Delete failed.");
      }
      setShowDeleteModal(null);
  };

  const onFileDrop = (e) => {
      const file = e.target.files[0];
      if (file) {
          setFileToUpload(file);
          setError(null);
          setSuccessMode(false);
          addLog(`STAGE: ${file.name} loaded. Waiting for encryption sequence...`);
      }
  };

  const startEncryption = async () => {
    if (!fileToUpload) return;

    setUploadStep(1);
    setLogs([]); 
    setSelectedFile(null); 
    
    addLog(`INIT: Starting Secure Protocol for ${fileToUpload.name}`);
    
    // Smooth Animation Sequence
    const isHybrid = cryptoMode === 'hybrid';
    
    setTimeout(() => { 
        setUploadStep(2); 
        addLog(isHybrid ? "PQC: Generating Ephemeral Keys..." : "RSA: Generating Baseline Keys..."); 
    }, 800);

    setTimeout(() => { 
        setUploadStep(3); 
        addLog(isHybrid ? "PQC: Encapsulating Shared Secret..." : "RSA: Encrypting Pre-Master Secret..."); 
    }, 2400); // More time to see it
    
    setTimeout(() => { 
        setUploadStep(4); 
        addLog("KDF: Deriving High-Entropy Session Key..."); 
    }, 4000);

    try {
      // Actually upload
      const res = await uploadFile(fileToUpload, cryptoMode); 
      
      setTimeout(() => {
        setUploadStep(5);
        addLog("AES: Encrypting Payload (GCM Mode)...");
        addLog("NET: Uploading Encrypted Blob...");
      }, 5500);
      
      setTimeout(() => {
        setUploadStep(0); // Stop animation
        setSuccessMode(true); // Show "New Upload" button
        addLog(`SUCCESS: File Sealed. ID: ${res.data.file_id}`);
        fetchFiles();
      }, 7000); // Finish after logs

    } catch (err) {
      setUploadStep(0);
      addLog("ERROR: Protocol Failed.");
      setError("Upload Failed. Check backend connection.");
    }
  };

  const resetUpload = () => {
      setFileToUpload(null);
      setSuccessMode(false);
      setUploadStep(0);
  };

  const handleDownload = async (file) => {
    if (file.mode !== 'hybrid') {
        setError("BASELINE RESTRICTION: Switch to Hybrid Mode to enable PQC Decryption.");
        return;
    }
    try {
      addLog(`REQ: Download Request for ${file.filename}`);
      await downloadFile(file.id, file.filename);
      addLog("SUCCESS: Integrity Verified & Decrypted.");
    } catch (err) {
      addLog("❌ FAILURE: Integrity Check Failed.");
      setError("CRITICAL: Ciphertext Tag Mismatch. The cloud file differs from the signature.");
    }
  };

  const getChartData = (metrics) => ({
      labels: ['PQC Encap', 'AES Encrypt', 'Total Latency'],
      datasets: [{
          label: 'Time (ms)',
          data: [metrics.pqc, metrics.aes, metrics.total],
          backgroundColor: ['#00ff9d', '#00f3ff', '#ffffff'],
          borderColor: ['#00ff9d', '#00f3ff', '#ffffff'],
          borderWidth: 1
      }]
  });

  return (
    <div className="p-8 space-y-6 relative h-full flex flex-col">
      
      {/* DELETE MODAL */}
      {showDeleteModal && (
          <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-50 backdrop-blur-sm">
              <div className="bg-scifi-panel border border-red-500 p-6 rounded-xl w-96 shadow-[0_0_50px_rgba(255,0,0,0.4)]">
                  <h3 className="text-xl font-bold text-red-500 mb-4 flex items-center gap-2">
                      <AlertTriangle /> CONFIRM DELETION
                  </h3>
                  <p className="text-gray-300 text-sm mb-6 leading-relaxed">
                      You are about to permanently destroy a secured object. <br/>
                      <span className="text-red-400 font-mono text-xs block mt-2">ID: {showDeleteModal}</span>
                      <span className="text-red-400 font-mono text-xs block">RECOVERY: IMPOSSIBLE</span>
                  </p>
                  <div className="flex justify-end gap-3">
                      <button onClick={() => setShowDeleteModal(null)} className="px-4 py-2 rounded border border-gray-600 hover:bg-white/10 text-gray-300 text-xs uppercase font-bold">Abort</button>
                      <button onClick={confirmDelete} className="px-4 py-2 rounded bg-red-600 hover:bg-red-700 text-white text-xs uppercase font-bold shadow-lg shadow-red-900/50">Destroy</button>
                  </div>
              </div>
          </div>
      )}

      {/* HEADER */}
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2 tracking-wide">QS-VAULT <span className="text-neon-green text-xs align-top px-1 rounded bg-neon-green/10">v1.0</span></h2>
          <p className="text-gray-400 text-sm font-mono">Post-Quantum Secure Gateway</p>
        </div>
        <div className="flex gap-4">
            <div className="flex flex-col items-end">
                <label className="text-[9px] text-gray-500 uppercase mb-1 tracking-wider">Crypto Protocol</label>
                <select 
                    value={cryptoMode} 
                    onChange={(e) => setCryptoMode(e.target.value)}
                    className="bg-black border border-gray-700 text-xs text-neon-blue p-2 rounded focus:outline-none focus:border-neon-blue"
                >
                    <option value="hybrid">Hybrid (PQC + AES)</option>
                    <option value="rsa">RSA-2048 (Baseline)</option>
                </select>
            </div>
            <div className="flex flex-col items-end">
                <label className="text-[9px] text-gray-500 uppercase mb-1 tracking-wider">Storage Target</label>
                <button 
                    onClick={() => { setStorageMode(storageMode === 'local' ? 'minio' : 'local'); addLog(`SYS: Switched Storage Target to ${storageMode === 'local' ? 'MinIO' : 'Local FS'}`); }}
                    className={`flex items-center gap-2 border text-xs p-2 rounded transition-all ${storageMode === 'local' ? 'bg-black border-gray-700 text-gray-300' : 'bg-neon-purple/10 border-neon-purple text-neon-purple'}`}
                >
                    {storageMode === 'local' ? <HardDrive size={14} /> : <Server size={14} />}
                    {storageMode === 'local' ? 'Local FS' : 'MinIO Cluster'}
                </button>
            </div>
        </div>
      </div>

      {error && (
        <div className="bg-red-900/20 border border-red-500 p-3 rounded text-red-400 text-sm flex items-center gap-3 font-mono">
            <AlertTriangle size={16} /> {error}
        </div>
      )}

      <div className="grid grid-cols-3 gap-6 flex-1 min-h-0">
        
        {/* LEFT COLUMN */}
        <div className="col-span-2 flex flex-col gap-6">
            
            {/* UPLOAD & STAGING AREA */}
            <div className="bg-scifi-panel border border-scifi-border rounded-xl p-1 relative overflow-hidden group">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-neon-green to-transparent opacity-30"></div>
                
                <div className="p-6 bg-black/40 rounded-lg">
                    <h3 className="text-white font-bold mb-6 flex items-center gap-2 text-sm uppercase tracking-wider">
                        <Upload size={16} className="text-neon-green" /> 
                        {uploadStep > 0 ? "Encryption Sequence Running..." : "Secure Upload Stage"}
                    </h3>
                    
                    {uploadStep > 0 ? (
                        <CryptoFlow currentStep={uploadStep} />
                    ) : successMode ? (
                        <div className="text-center py-8">
                            <div className="inline-flex p-4 rounded-full bg-neon-green/10 mb-4 border border-neon-green/30">
                                <Activity className="text-neon-green" size={32} />
                            </div>
                            <h4 className="text-white font-bold text-lg mb-1">Encryption Successful</h4>
                            <p className="text-gray-500 text-xs mb-6">Object sealed and persisted to storage.</p>
                            <button onClick={resetUpload} className="px-6 py-2 bg-white text-black font-bold uppercase text-xs rounded hover:bg-neon-green transition-colors flex items-center gap-2 mx-auto">
                                <RefreshCw size={14} /> Encrypt Another File
                            </button>
                        </div>
                    ) : !fileToUpload ? (
                        <div className="relative border-2 border-dashed border-gray-800 rounded-lg h-48 flex flex-col items-center justify-center hover:border-neon-green/50 hover:bg-white/5 transition-all">
                            <input 
                                type="file" 
                                onChange={onFileDrop} 
                                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" 
                            />
                            <Upload className="text-gray-600 mb-4" size={32} />
                            <p className="text-gray-300 font-bold text-sm">Drop file to Stage</p>
                            <p className="text-gray-600 text-xs mt-2">Ready for PQC-KEM Encap</p>
                        </div>
                    ) : (
                        <div className="border border-neon-green/30 bg-neon-green/5 rounded-lg p-8 text-center relative overflow-hidden">
                            <div className="absolute top-0 left-0 w-1 h-full bg-neon-green"></div>
                            <FileText className="mx-auto text-neon-green mb-3" size={40} />
                            <p className="text-xl font-bold text-white mb-1">{fileToUpload.name}</p>
                            <p className="text-xs text-gray-400 mb-6 font-mono">{(fileToUpload.size / 1024).toFixed(2)} KB • WAITING</p>
                            
                            <div className="flex justify-center gap-4">
                                <button onClick={() => setFileToUpload(null)} className="px-6 py-2 rounded border border-gray-700 text-gray-400 hover:text-white hover:border-gray-500 uppercase font-bold text-xs">
                                    Cancel
                                </button>
                                <button onClick={startEncryption} className="px-6 py-2 rounded bg-neon-green text-black hover:bg-white hover:shadow-[0_0_20px_rgba(0,255,157,0.5)] uppercase font-bold text-xs flex items-center gap-2 transition-all">
                                    <Play size={14} fill="black" /> Engage Protocol
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* TERMINAL */}
            <div className="bg-black border border-gray-800 rounded-xl p-4 flex-1 min-h-[150px] overflow-hidden flex flex-col shadow-inner">
                <div className="flex items-center gap-2 text-gray-500 border-b border-gray-800 pb-2 mb-2 bg-black">
                    <Terminal size={14} /> CRYPTO_KERNEL_LOGS
                </div>
                <div className="overflow-y-auto custom-scrollbar flex-1">
                    {logs.map((log, i) => <p key={i} className="text-neon-green/80 mb-1 font-mono text-[10px] tracking-tight">{log}</p>)}
                    {logs.length === 0 && <p className="text-gray-800 italic text-[10px]">System Idle. Waiting for input...</p>}
                </div>
            </div>
        </div>

        {/* RIGHT COLUMN: FILE LIST */}
        <div className="col-span-1 bg-scifi-panel border border-scifi-border rounded-xl p-1 flex flex-col h-full overflow-hidden">
             <div className="p-4 bg-black/20 border-b border-gray-800">
                <h3 className="text-white font-bold text-sm flex items-center gap-2">
                    <Server size={14} className="text-neon-blue"/> Vault Contents
                </h3>
             </div>
             
             <div className="p-4 space-y-2 overflow-y-auto custom-scrollbar flex-1">
                {files.length === 0 && <p className="text-gray-600 text-center text-xs mt-10 italic">Vault Empty</p>}
                {files.map(file => (
                    <div 
                        key={file.id} 
                        onClick={() => setSelectedFile(file)} 
                        className={`p-3 rounded border transition cursor-pointer group relative
                            ${selectedFile?.id === file.id ? 'bg-neon-blue/10 border-neon-blue' : 'bg-white/5 border-transparent hover:border-gray-600'}`}
                    >
                        <div className="flex justify-between items-start mb-2">
                            <p className="text-xs text-white truncate w-32 font-bold">{file.filename}</p>
                            <span className={`text-[9px] px-1.5 py-0.5 rounded font-bold uppercase tracking-wide
                                ${file.mode === 'hybrid' ? 'text-neon-green bg-neon-green/10' : 'text-neon-purple bg-neon-purple/10'}`}>
                                {file.mode === 'hybrid' ? 'PQC' : 'RSA'}
                            </span>
                        </div>
                        <p className="text-[10px] text-gray-500 font-mono">{new Date(file.date).toLocaleDateString()} • {(file.size/1024).toFixed(1)} KB</p>

                        {/* Hover Actions */}
                        <div className="absolute right-2 bottom-2 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                             <button onClick={(e) => { e.stopPropagation(); setShowDeleteModal(file.id); }} className="text-red-500 hover:text-white p-1 hover:bg-red-500/20 rounded">
                                <Trash2 size={14} />
                            </button>
                            <button onClick={(e) => { e.stopPropagation(); handleDownload(file); }} className="text-neon-blue hover:text-white p-1 hover:bg-neon-blue/20 rounded">
                                <Download size={14} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>
            
            {/* SELECTED FILE GRAPH */}
            {selectedFile && (
                <div className="p-4 border-t border-gray-800 bg-black/50">
                     <div className="flex justify-between items-center mb-4">
                        <span className="text-xs font-bold text-gray-400">METRICS: {selectedFile.id}</span>
                        <button onClick={() => setSelectedFile(null)} className="text-gray-600 hover:text-white"><X size={12}/></button>
                     </div>
                     <div className="h-32">
                        <Bar 
                            data={getChartData(selectedFile.metrics)} 
                            options={{
                                responsive: true,
                                maintainAspectRatio: false,
                                plugins: { legend: { display: false } },
                                scales: {
                                    y: { grid: { color: '#222' }, ticks: { color: '#555', font: {size: 8} } },
                                    x: { grid: { display: false }, ticks: { color: '#888', font: {size: 8} } }
                                }
                            }} 
                        />
                     </div>
                </div>
            )}
        </div>

      </div>
    </div>
  );
};

export default Dashboard;
